#!/usr/bin/env bash
# Copies the store images generated by test/goldens/store_test.dart into the
# fastlane folders, as the stores want them: screenshots and the feature
# graphic as JPEG without alpha, and the Play icon as a 512 px PNG resized
# from the launcher icon (assets/branding/app_icon.png).
set -euo pipefail

cd "$(dirname "$0")/.."

src=test/goldens/goldens/store

jpeg() { sips -s format jpeg -s formatOptions 92 "$1" --out "$2" >/dev/null; }

for locale in en-US es-ES; do
  ios=fastlane/screenshots/$locale
  play=fastlane/metadata/android/$locale/images
  rm -rf "$ios" "$play"
  mkdir -p "$ios" "$play/phoneScreenshots"

  for shot in "$src/app_store/$locale"/*.png; do
    jpeg "$shot" "$ios/$(basename "${shot%.png}").jpg"
  done
  for shot in "$src/play/$locale"/[0-9]*.png; do
    jpeg "$shot" "$play/phoneScreenshots/$(basename "${shot%.png}").jpg"
  done
  jpeg "$src/play/$locale/feature_graphic.png" "$play/featureGraphic.jpg"
  sips -z 512 512 assets/branding/app_icon.png --out "$play/icon.png" >/dev/null
done
echo "Store images copied into fastlane/."
